#!/usr/bin/env node
/**
 * Builds the Windows and macOS icon assets from the single master artwork in
 * build/icon-source.png.
 *
 * Why this reads and resamples the PNG itself instead of importing an image
 * library: adding `sharp` (native, ~30 MB of platform binaries) to draw one
 * icon is a supply-chain and build-time cost the app does not need. The
 * decoder below handles the only shape the master artwork has — 8-bit,
 * non-interlaced, RGB or RGBA — and fails loudly on anything else rather than
 * producing a silently wrong icon.
 *
 * Outputs, all regenerated by `npm run icon`:
 *   build/icon.png    1024x1024 RGBA  — electron-builder source for mac/linux
 *   build/icon.ico    multi-size DIB  — Windows exe icon and installer
 *   build/icon.icns   multi-size PNG  — macOS .app bundle
 *
 * The 16/24/32 px entries are resampled from the 1024 master with an area
 * filter, not by nearest-neighbour, because that is the size Windows actually
 * draws in the taskbar and title bar.
 */
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const buildDir = path.join(root, 'build');
const sourcePng = path.join(buildDir, 'icon-source.png');

/** Windows draws every one of these; the ICO carries them all. */
const ICO_SIZES = [16, 24, 32, 48, 64, 128, 256];
/** macOS accepts PNG-payload entries for these type codes. */
const ICNS_SIZES = [
  ['icp4', 16],
  ['icp5', 32],
  ['icp6', 64],
  ['ic07', 128],
  ['ic08', 256],
  ['ic09', 512],
  ['ic10', 1024],
];

/* ------------------------------------------------------------- PNG decode --- */

function crc32(buffer) {
  let crc = 0xffffffff;
  for (let i = 0; i < buffer.length; i += 1) {
    crc ^= buffer[i];
    for (let bit = 0; bit < 8; bit += 1) {
      crc = crc & 1 ? (crc >>> 1) ^ 0xedb88320 : crc >>> 1;
    }
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function paeth(a, b, c) {
  const p = a + b - c;
  const pa = Math.abs(p - a);
  const pb = Math.abs(p - b);
  const pc = Math.abs(p - c);
  if (pa <= pb && pa <= pc) return a;
  return pb <= pc ? b : c;
}

/**
 * Decodes an 8-bit, non-interlaced RGB (colour type 2) or RGBA (colour type 6)
 * PNG into a flat RGBA buffer.
 */
export function decodePng(buffer) {
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  if (buffer.length < 8 || !buffer.subarray(0, 8).equals(signature)) {
    throw new Error('icon-source.png is not a PNG (bad signature)');
  }

  let offset = 8;
  let width = 0;
  let height = 0;
  let bitDepth = 0;
  let colorType = 0;
  let interlace = 0;
  const idat = [];

  while (offset < buffer.length) {
    if (offset + 8 > buffer.length) throw new Error('icon-source.png is truncated mid-chunk');
    const length = buffer.readUInt32BE(offset);
    const type = buffer.toString('ascii', offset + 4, offset + 8);
    const dataEnd = offset + 8 + length;
    if (dataEnd + 4 > buffer.length) throw new Error(`chunk ${type} runs past the end of the file`);
    const data = buffer.subarray(offset + 8, dataEnd);

    // A plausible-looking header over a corrupt body would decode to garbage and
    // be written as a valid-looking icon. Check the chunk CRC before using it.
    const expectedCrc = buffer.readUInt32BE(dataEnd);
    const actualCrc = crc32(buffer.subarray(offset + 4, dataEnd));
    if (expectedCrc !== actualCrc) {
      throw new Error(`chunk ${type} failed its CRC check (corrupt or truncated file)`);
    }

    if (type === 'IHDR') {
      width = data.readUInt32BE(0);
      height = data.readUInt32BE(4);
      bitDepth = data[8];
      colorType = data[9];
      interlace = data[12];
    } else if (type === 'IDAT') {
      idat.push(data);
    } else if (type === 'IEND') {
      break;
    }
    offset = dataEnd + 4;
  }

  if (width <= 0 || height <= 0) throw new Error('icon-source.png has no IHDR');
  if (bitDepth !== 8) throw new Error(`unsupported bit depth ${bitDepth}; expected 8`);
  if (colorType !== 2 && colorType !== 6) {
    throw new Error(`unsupported colour type ${colorType}; expected 2 (RGB) or 6 (RGBA)`);
  }
  if (interlace !== 0) throw new Error('interlaced PNG is not supported; re-save as non-interlaced');

  const channels = colorType === 6 ? 4 : 3;
  const stride = width * channels;
  const raw = zlib.inflateSync(Buffer.concat(idat));
  const expected = (stride + 1) * height;
  if (raw.length !== expected) {
    throw new Error(`inflated size ${raw.length} does not match ${expected}`);
  }

  const pixels = Buffer.alloc(width * height * 4);
  const prior = Buffer.alloc(stride);
  const line = Buffer.alloc(stride);

  for (let y = 0; y < height; y += 1) {
    const filter = raw[y * (stride + 1)];
    const start = y * (stride + 1) + 1;
    raw.copy(line, 0, start, start + stride);

    for (let i = 0; i < stride; i += 1) {
      const a = i >= channels ? line[i - channels] : 0;
      const b = prior[i];
      const c = i >= channels ? prior[i - channels] : 0;
      switch (filter) {
        case 0:
          break;
        case 1:
          line[i] = (line[i] + a) & 0xff;
          break;
        case 2:
          line[i] = (line[i] + b) & 0xff;
          break;
        case 3:
          line[i] = (line[i] + ((a + b) >> 1)) & 0xff;
          break;
        case 4:
          line[i] = (line[i] + paeth(a, b, c)) & 0xff;
          break;
        default:
          throw new Error(`unknown PNG filter ${filter} on row ${y}`);
      }
    }

    for (let x = 0; x < width; x += 1) {
      const s = x * channels;
      const d = (y * width + x) * 4;
      pixels[d] = line[s];
      pixels[d + 1] = line[s + 1];
      pixels[d + 2] = line[s + 2];
      pixels[d + 3] = channels === 4 ? line[s + 3] : 255;
    }
    line.copy(prior);
  }

  return { width, height, pixels };
}

/* -------------------------------------------------------------- resample --- */

/**
 * Area-average resample (a box filter with exact fractional coverage). Correct
 * for the heavy downscales an icon needs; a bilinear stretch would alias the
 * thin circuit lines of the mark into noise at 16 px.
 */
function resample(source, srcW, srcH, dstW, dstH) {
  if (srcW === dstW && srcH === dstH) return Buffer.from(source);

  const out = Buffer.alloc(dstW * dstH * 4);
  const scaleX = srcW / dstW;
  const scaleY = srcH / dstH;

  for (let dy = 0; dy < dstH; dy += 1) {
    const y0 = dy * scaleY;
    const y1 = Math.min(srcH, y0 + scaleY);
    const sy0 = Math.floor(y0);
    const sy1 = Math.ceil(y1);

    for (let dx = 0; dx < dstW; dx += 1) {
      const x0 = dx * scaleX;
      const x1 = Math.min(srcW, x0 + scaleX);
      const sx0 = Math.floor(x0);
      const sx1 = Math.ceil(x1);

      let r = 0;
      let g = 0;
      let b = 0;
      let a = 0;
      let weight = 0;

      for (let sy = sy0; sy < sy1; sy += 1) {
        const wy = Math.min(sy + 1, y1) - Math.max(sy, y0);
        if (wy <= 0) continue;
        for (let sx = sx0; sx < sx1; sx += 1) {
          const wx = Math.min(sx + 1, x1) - Math.max(sx, x0);
          if (wx <= 0) continue;
          const w = wx * wy;
          const i = (sy * srcW + sx) * 4;
          // Premultiply so transparent edges do not bleed dark fringes.
          const alpha = source[i + 3] / 255;
          r += source[i] * alpha * w;
          g += source[i + 1] * alpha * w;
          b += source[i + 2] * alpha * w;
          a += source[i + 3] * w;
          weight += w;
        }
      }

      const d = (dy * dstW + dx) * 4;
      const alphaOut = a / weight; // 0..255
      if (alphaOut > 0) {
        // Un-premultiply: r/g/b above are still multiplied by alpha.
        const alphaScale = 255 / alphaOut;
        out[d] = Math.round(Math.min(255, (r / weight) * alphaScale));
        out[d + 1] = Math.round(Math.min(255, (g / weight) * alphaScale));
        out[d + 2] = Math.round(Math.min(255, (b / weight) * alphaScale));
      }
      out[d + 3] = Math.round(alphaOut);
    }
  }

  return out;
}

/* ------------------------------------------------------------- PNG encode --- */

function chunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([length, body, crc]);
}

function encodePng(width, height, rgba) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;

  const stride = width * 4;
  const raw = Buffer.alloc((stride + 1) * height);
  for (let y = 0; y < height; y += 1) {
    raw[y * (stride + 1)] = 0;
    rgba.copy(raw, y * (stride + 1) + 1, y * stride, y * stride + stride);
  }

  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', zlib.deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

/* --------------------------------------------------------------- ICO ------- */

/**
 * One 32bpp BMP/DIB directory entry. DIB (rather than PNG-in-ICO) is used for
 * every size so the file is accepted by the older icon parsers that rcedit and
 * some Windows shell paths still use.
 */
function icoEntry(size, rgba) {
  const header = Buffer.alloc(40);
  header.writeUInt32LE(40, 0);
  header.writeInt32LE(size, 4);
  header.writeInt32LE(size * 2, 8); // XOR + AND mask
  header.writeUInt16LE(1, 12);
  header.writeUInt16LE(32, 14);
  header.writeUInt32LE(0, 16); // BI_RGB
  header.writeUInt32LE(size * size * 4, 20);

  const xor = Buffer.alloc(size * size * 4);
  for (let y = 0; y < size; y += 1) {
    const srcRow = size - 1 - y; // DIB rows are bottom-up
    for (let x = 0; x < size; x += 1) {
      const s = (srcRow * size + x) * 4;
      const d = (y * size + x) * 4;
      xor[d] = rgba[s + 2];
      xor[d + 1] = rgba[s + 1];
      xor[d + 2] = rgba[s];
      xor[d + 3] = rgba[s + 3];
    }
  }

  const maskRowBytes = Math.ceil(size / 32) * 4;
  const and = Buffer.alloc(maskRowBytes * size); // all zero: fully opaque mask
  return { size, data: Buffer.concat([header, xor, and]) };
}

function encodeIco(entries) {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0);
  header.writeUInt16LE(1, 2);
  header.writeUInt16LE(entries.length, 4);

  let offset = 6 + entries.length * 16;
  const directory = [];
  for (const entry of entries) {
    const row = Buffer.alloc(16);
    row[0] = entry.size >= 256 ? 0 : entry.size;
    row[1] = entry.size >= 256 ? 0 : entry.size;
    row[2] = 0;
    row[3] = 0;
    row.writeUInt16LE(1, 4);
    row.writeUInt16LE(32, 6);
    row.writeUInt32LE(entry.data.length, 8);
    row.writeUInt32LE(offset, 12);
    offset += entry.data.length;
    directory.push(row);
  }

  return Buffer.concat([header, ...directory, ...entries.map((e) => e.data)]);
}

/* --------------------------------------------------------------- ICNS ------ */

function encodeIcns(pngBySize) {
  const blocks = [];
  for (const [type, size] of ICNS_SIZES) {
    const png = pngBySize.get(size);
    if (!png) continue;
    const head = Buffer.alloc(8);
    head.write(type, 0, 4, 'ascii');
    head.writeUInt32BE(png.length + 8, 4);
    blocks.push(Buffer.concat([head, png]));
  }

  const body = Buffer.concat(blocks);
  const header = Buffer.alloc(8);
  header.write('icns', 0, 4, 'ascii');
  header.writeUInt32BE(body.length + 8, 4);
  return Buffer.concat([header, body]);
}

/* ----------------------------------------------------------------- main ---- */

function main() {
  const master = decodePng(fs.readFileSync(sourcePng));
  if (master.width !== master.height) {
    throw new Error(`icon-source.png must be square, got ${master.width}x${master.height}`);
  }

  fs.mkdirSync(buildDir, { recursive: true });

  const cache = new Map();
  const at = (size) => {
    if (!cache.has(size)) cache.set(size, resample(master.pixels, master.width, master.height, size, size));
    return cache.get(size);
  };

  const iconPng = encodePng(1024, 1024, at(1024));
  const ico = encodeIco(ICO_SIZES.map((size) => icoEntry(size, at(size))));
  const pngBySize = new Map(ICNS_SIZES.map(([, size]) => [size, encodePng(size, size, at(size))]));
  const icns = encodeIcns(pngBySize);

  // Write-then-rename so a crash mid-write cannot leave a half-icon that a
  // later packaging step would happily embed.
  const writeAtomic = (name, bytes) => {
    const target = path.join(buildDir, name);
    const temp = `${target}.tmp`;
    fs.writeFileSync(temp, bytes);
    fs.renameSync(temp, target);
  };
  writeAtomic('icon.png', iconPng);
  writeAtomic('icon.ico', ico);
  writeAtomic('icon.icns', icns);

  // Optional per-size PNG dump, used to eyeball the 16/32 px rendering.
  const previewDir = process.env.ICON_PREVIEW_DIR;
  if (previewDir) {
    fs.mkdirSync(previewDir, { recursive: true });
    for (const size of [16, 32, 48, 256]) {
      fs.writeFileSync(path.join(previewDir, `icon-${size}.png`), encodePng(size, size, at(size)));
    }
  }

  const upscaled = master.width < 1024 ? ` (upscaled from ${master.width}px)` : '';
  process.stdout.write(
    `[icon] source ${master.width}x${master.height}${upscaled} -> icon.png ${iconPng.length} B, ` +
      `icon.ico ${ico.length} B (${ICO_SIZES.join('/')}), icon.icns ${icns.length} B\n`,
  );
}

main();
